import itertools

# Represent vectors as integers 0..31 (5 bits)
def add(a, b):
    return a ^ b

def subspace_basis(b1, b2):
    # b1, b2 linearly independent
    return {0, b1, b2, add(b1, b2)}

# All non-zero vectors
nonzero = list(range(1, 32))

# Generate all 2D subspaces
subspaces = []
seen = set()
for b1 in range(1, 32):
    for b2 in range(b1+1, 32):
        # check independence: b2 not in span of b1, i.e., b2 != 0 and b2 != b1
        # Since b1 != 0 and b2 > b1, they are independent if b2 != b1 (always true)
        # Actually need to ensure b2 is not a multiple of b1. Over GF(2), multiples are 0 and b1.
        # So any b2 != b1, b2 != 0 is independent.
        s = frozenset(subspace_basis(b1, b2))
        if s not in seen:
            seen.add(s)
            subspaces.append(s)

print("Total subspaces:", len(subspaces))

# Function to check if two subspaces intersect trivially
def disjoint_subspaces(s1, s2):
    return len(s1.intersection(s2)) == 1  # only 0

# Greedy search for 7 subspaces
def find_subspaces(k=7):
    # Try recursive backtracking
    result = []
    used_nonzero = set()

    def backtrack(start):
        if len(result) == k:
            return True
        # Try adding a subspace
        for i, s in enumerate(subspaces[start:], start):
            nonzero_s = s - {0}
            if nonzero_s.isdisjoint(used_nonzero):
                # add
                result.append(s)
                used_nonzero.update(nonzero_s)
                if backtrack(i+1):
                    return True
                # backtrack
                result.pop()
                used_nonzero.difference_update(nonzero_s)
        return False

    if backtrack(0):
        return result
    else:
        return None

subs = find_subspaces(7)
print("Found subspaces:", len(subs) if subs else None)
if subs:
    for i, s in enumerate(subs):
        print(i, sorted(s))

import itertools

def add(a, b):
    return a ^ b

subs = [
    frozenset({0, 1, 2, 3}),
    frozenset({0, 4, 8, 12}),
    frozenset({0, 5, 10, 15}),
    frozenset({0, 6, 11, 13}),
    frozenset({0, 7, 16, 23}),
    frozenset({0, 9, 17, 24}),
    frozenset({0, 14, 18, 28}),
]

def get_cosets(subspace):
    reps = []
    used = set()
    for v in range(32):
        coset = frozenset({add(v, s) for s in subspace})
        if coset not in used:
            used.add(coset)
            reps.append(v)
    assert len(reps) == 8
    cosets = []
    for r in reps:
        cosets.append(frozenset({add(r, s) for s in subspace}))
    return cosets

schedule = []
for w, S in enumerate(subs):
    cosets = get_cosets(S)
    week_map = {}
    for g, coset in enumerate(cosets):
        for p in coset:
            week_map[p] = g
    schedule.append(week_map)

flat = []
for w in range(7):
    for p in range(32):
        flat.append(schedule[w][p])

print("Flat list:")
print(flat)

# Verify
pair_count = {}
for w, week_map in enumerate(schedule):
    groups = [[] for _ in range(8)]
    for p in range(32):
        groups[week_map[p]].append(p)
    for g in groups:
        for p1, p2 in itertools.combinations(g, 2):
            pair = tuple(sorted((p1, p2)))
            pair_count[pair] = pair_count.get(pair, 0) + 1

print("\nMax pair count:", max(pair_count.values()))
print("Total pairs:", len(pair_count))
